/* Calendar, feedback and timeline interactions; all persistence stays in this browser. */
const WorkspaceUI=(function(M){
 const KEY='meterwise-workspace-v1',q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const dateFormat=new Intl.DateTimeFormat('en-US',{timeZone:M.ZONE,month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZoneName:'short'});
 const time=s=>dateFormat.format(new Date(s)),options=(items,empty='')=>(empty?`<option value="">${h(empty)}</option>`:'')+Object.entries(items).map(([v,label])=>`<option value="${h(v)}">${h(label)}</option>`).join('');
 let data,ctx,records=M.emptyState(),lastRaw=null,storageError='',showCalendar=true,viewAlert=null,zoom='event',editing=null,pending=null;
 const drafts=new Map();
 const feedbackFor=a=>records.feedback.find(r=>r.datasetRevision===ctx.datasetRevision&&r.alertId===a.id);
 const scopeName=id=>id==='ALL'?'Campus-wide':data.buildings.find(b=>b.id===id)?.name||id;
 const epoch=i=>Date.parse(data.start)+i*900000;
 const message=(selector,text)=>{q(selector).textContent=text;};
 function write(next){if(storageError)throw Error(storageError);if(localStorage.getItem(KEY)!==lastRaw)throw Error('Records changed in another tab. Reload before saving to avoid replacing those changes.');const raw=JSON.stringify(next);localStorage.setItem(KEY,raw);records=next;lastRaw=raw;}
 function modal(id,title,body){document.body.insertAdjacentHTML('beforeend',`<dialog id="${id}" aria-labelledby="${id}-title"><div class="modal-heading"><h2 id="${id}-title">${title}</h2><button type="button" class="icon-button" data-close="${id}" aria-label="Close ${title}">×</button></div>${body}</dialog>`);q(`#${id} [data-close]`).onclick=()=>q('#'+id).close();}
 function seed(){return [
  {id:'demo-maintenance',scope:'ADM',type:'maintenance',title:'Synthetic example: overnight HVAC maintenance',start:M.wallToIso('2026-10-16T00:00'),end:M.wallToIso('2026-10-16T06:00'),notes:'Demo only. Planned testing could explain some after-hours load; verify actual work logs.',isExample:true},
  {id:'demo-closure',scope:'LIB',type:'closure',title:'Synthetic example: library closure',start:M.wallToIso('2026-10-17T10:00'),end:M.wallToIso('2026-10-17T18:00'),notes:'Demo only. A closure is additional context, not confirmation that an electrical deviation is harmless.',isExample:true},
  {id:'demo-evening-event',scope:'STU',type:'occupancy',title:'Synthetic example: evening campus event',start:M.wallToIso('2026-10-11T18:00'),end:M.wallToIso('2026-10-11T22:00'),notes:'Demo only. Expected occupancy extends into the evening.',isExample:true}
 ];}
 async function init(dataset,raw){
  data=dataset;ctx={datasetRevision:await M.revisionFor(data,raw),buildingIds:data.buildings.map(b=>b.id),alertIds:data.alerts.map(a=>a.id)};
  try{lastRaw=localStorage.getItem(KEY);if(lastRaw!==null){const saved=JSON.parse(lastRaw),preview=M.previewImport({format:M.FORMAT,...saved},M.emptyState(),ctx);if(preview.invalid.length)throw Error('Stored records failed validation.');records=M.mergeImport(M.emptyState(),preview);}else{records.calendar=seed().map(r=>M.calendarRecord(r,ctx));write(records);}}catch(e){storageError='Browser records are read-only: '+e.message;}
  q('.toolbar').insertAdjacentHTML('afterend',`<div class="workspace-tools"><button class="button light" id="open-calendar">◷ Operating calendar</button><label><input type="checkbox" id="calendar-overlay" checked> Show calendar on charts</label><button class="text-button" id="open-records">Export / import records</button><span>Saved in this browser only · Los Angeles time</span></div><p id="workspace-error" class="form-error" role="alert"></p>`);
  q('#workspace-error').textContent=storageError;
  q('.inbox-filters').insertAdjacentHTML('beforeend',`<select id="feedback-filter" aria-label="Filter investigation outcome"><option value="all">All user assessments</option><option value="none">No feedback</option>${options(M.OUTCOMES)}</select>`);
  q('#inbox').insertAdjacentHTML('beforebegin','<div id="feedback-summary" class="feedback-summary"></div>');
  const scopes={ALL:'Campus-wide',...Object.fromEntries(data.buildings.map(b=>[b.id,b.name]))};
  modal('calendar-dialog','Operating calendar',`<p class="small">Explicit dated intervals in America/Los_Angeles time. Changes stay in this browser. Calendar context does not change detector output.</p><div class="calendar-layout"><section><div class="calendar-list-heading"><h3>Calendar entries</h3><button type="button" class="text-button" id="calendar-new">+ New entry</button></div><div id="calendar-list"></div></section><form id="calendar-form" novalidate><h3 id="calendar-form-title">New calendar entry</h3><label>Building scope<select name="scope" aria-label="Calendar building scope">${options(scopes)}</select></label><label>Context type<select name="type" aria-label="Calendar context type">${options(M.TYPES)}</select></label><label>Title<input name="title" aria-label="Calendar title" maxlength="120" required></label><label>Start · Los Angeles<input name="start" aria-label="Calendar start" type="datetime-local" required></label><label>End · Los Angeles<input name="end" aria-label="Calendar end" type="datetime-local" required></label><label>Notes<textarea name="notes" aria-label="Calendar notes" maxlength="2000" rows="3"></textarea></label><p id="calendar-error" class="form-error" role="alert"></p><button class="button dark" type="submit">Save calendar entry</button></form></div>`);
  modal('records-dialog','Transfer browser records',`<p class="small">Export calendar entries and assessments as JSON to transfer them between browsers. Feedback remains tied to its exact dataset fingerprint.</p><button class="button light" id="records-export">↓ Export JSON</button><label class="import-label">Choose a Meterwise JSON export<input id="records-file" aria-label="Import records JSON" type="file" accept=".json,application/json"></label><p id="records-error" class="form-error" role="alert"></p><div id="import-preview"></div><div id="import-actions" hidden><label><input type="checkbox" id="replace-conflicts"> Replace the conflicting records shown above (explicit overwrite)</label><p class="small">Invalid records are skipped. Existing records are kept unless replacement is selected.</p><button class="button dark" id="apply-import">Apply valid new records</button></div><p id="records-status" role="status"></p>`);
  modal('alert-chooser','Choose an overlapping alert','<p>Several alerts overlap this part of the timeline. Choose the event you want to investigate.</p><div id="alert-choices"></div>');
  q('#open-calendar').onclick=()=>openCalendar();q('#calendar-new').onclick=()=>editCalendar();q('#calendar-form').onsubmit=saveCalendar;
  q('#calendar-overlay').onchange=e=>{showCalendar=e.target.checked;render();};q('#feedback-filter').onchange=renderInbox;
  q('#open-records').onclick=()=>q('#records-dialog').showModal();q('#records-export').onclick=exportJSON;q('#records-file').onchange=previewFile;q('#replace-conflicts').onchange=updateApplyLabel;q('#apply-import').onclick=applyImport;
 }
 function editCalendar(entry=null,alert=null){
  editing=entry;const form=q('#calendar-form'),date=alert?M.isoToWall(new Date(epoch(alert.start)).toISOString()):q('#date').value+'T08:00';
  form.elements.scope.value=entry?.scope||alert?.building||q('#building').value;form.elements.type.value=entry?.type||'maintenance';form.elements.title.value=entry?.title||'';form.elements.start.value=entry?M.isoToWall(entry.start):date;form.elements.end.value=entry?M.isoToWall(entry.end):alert?M.isoToWall(new Date(epoch(alert.end)).toISOString()):q('#date').value+'T17:00';form.elements.notes.value=entry?.notes||'';q('#calendar-form-title').textContent=entry?'Edit calendar entry':'New calendar entry';message('#calendar-error','');
 }
 function renderCalendarList(){q('#calendar-list').innerHTML=records.calendar.length?[...records.calendar].sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).map(e=>`<article class="calendar-entry"><strong>${h(e.title)}</strong><span>${h(scopeName(e.scope))} · ${h(M.TYPES[e.type])}</span><time>${h(time(e.start))} – ${h(time(e.end))}</time>${e.isExample?'<small class="example-tag">Synthetic demo example</small>':''}<p>${h(e.notes)}</p><div><button type="button" class="text-button" data-edit-calendar="${h(e.id)}">Edit</button><button type="button" class="text-button" data-delete-calendar="${h(e.id)}">Delete</button></div></article>`).join(''):'<p>No calendar entries. Add a dated operating interval.</p>';
  all('[data-edit-calendar]').forEach(el=>el.onclick=()=>editCalendar(records.calendar.find(e=>e.id===el.dataset.editCalendar)));
  all('[data-delete-calendar]').forEach(el=>el.onclick=()=>{try{write({...records,calendar:records.calendar.filter(e=>e.id!==el.dataset.deleteCalendar)});if(editing?.id===el.dataset.deleteCalendar)editCalendar();renderCalendarList();render();}catch(e){message('#calendar-error',e.message);}});
 }
 function openCalendar(alert=null,entry=null){renderCalendarList();editCalendar(entry,alert);q('#calendar-dialog').showModal();}
 function saveCalendar(event){event.preventDefault();const f=q('#calendar-form').elements;try{const entry=M.calendarRecord({id:editing?.id||'cal-'+crypto.randomUUID(),scope:f.scope.value,type:f.type.value,title:f.title.value,start:M.wallToIso(f.start.value),end:M.wallToIso(f.end.value),notes:f.notes.value,isExample:editing?.isExample||false},ctx);write({...records,calendar:[...records.calendar.filter(e=>e.id!==entry.id),entry]});editing=entry;renderCalendarList();render();message('#calendar-error','');q('#calendar-form-title').textContent='Saved calendar entry';notify('Calendar entry saved');}catch(e){message('#calendar-error',e.message);}}
 function matchesFeedback(a){const value=q('#feedback-filter')?.value||'all',feedback=feedbackFor(a);return value==='all'||(value==='none'?!feedback:feedback?.outcome===value);}
 function alertSelected(id){if(viewAlert!==id){viewAlert=id;zoom='event';}if(q('#feedback-filter'))q('#feedback-filter').value='all';}
 function focusInvestigation(){const panel=q('#investigation'),heading=panel.querySelector('h2');if(!heading)return;heading.tabIndex=-1;panel.scrollIntoView({block:'start'});heading.focus({preventScroll:true});}
 function boundsFor(a,total){if(viewAlert!==a.id){viewAlert=a.id;zoom='event';}return M.zoomBounds(a,zoom,total);}
 function supportingWindows(a){return zoom==='history'?(a.evidence_events||[]):[];}
 function renderFeedback(a){
  const saved=feedbackFor(a),key=JSON.stringify([ctx.datasetRevision,a.id]),draft=drafts.get(key),values=draft||saved||{};
  q('#investigation .actions').insertAdjacentHTML('beforebegin',`<section class="feedback-panel"><div class="overline">USER ASSESSMENT · SEPARATE FROM DETECTOR GUESS</div><h3>Investigation feedback</h3><form id="feedback-form" novalidate><label>Outcome<select name="outcome" aria-label="Investigation outcome" required>${options(M.OUTCOMES,'Choose an outcome')}</select></label><label>Possible cause · optional<select name="cause" aria-label="Investigation cause">${options(M.CAUSES,'Not specified')}</select></label><label>Investigation notes · optional<textarea name="notes" aria-label="Investigation notes" maxlength="2000" rows="3"></textarea></label><p id="feedback-error" class="form-error" role="alert"></p><div class="feedback-save"><button class="button dark" type="submit">Save feedback</button><span id="feedback-saved" role="status">${draft?'Unsaved changes':saved?'Saved '+h(time(saved.updatedAt)):'No feedback saved'}</span></div></form><p class="small">Saving feedback does not change review status, raw detection, or benchmark results. Browser-local · dataset ${h(ctx.datasetRevision.slice(0,15))}…</p></section>`);
  const form=q('#feedback-form');form.elements.outcome.value=values.outcome||'';form.elements.cause.value=values.cause||'';form.elements.notes.value=values.notes||'';
  form.oninput=()=>{drafts.set(key,{outcome:form.elements.outcome.value,cause:form.elements.cause.value,notes:form.elements.notes.value});message('#feedback-saved','Unsaved changes');};
  form.onsubmit=e=>{e.preventDefault();try{const createdAt=saved?.createdAt||new Date().toISOString(),updatedAt=new Date(Math.max(Date.now(),Date.parse(createdAt))).toISOString();const record=M.feedbackRecord({alertId:a.id,datasetRevision:ctx.datasetRevision,outcome:form.elements.outcome.value,cause:form.elements.cause.value,notes:form.elements.notes.value,createdAt,updatedAt},ctx);write({...records,feedback:[...records.feedback.filter(r=>M.feedbackKey(r)!==M.feedbackKey(record)),record]});drafts.delete(key);renderInbox();notify('Investigation feedback saved; review status unchanged');}catch(e){message('#feedback-error',e.message);}};
 }
 function investigation(a){
  const range=boundsFor(a,data.days*96),chart=q('#detail-chart');chart.insertAdjacentHTML('beforebegin',`<div class="chart-view-controls" role="group" aria-label="Investigation chart view"><button type="button" data-zoom="event" aria-pressed="${zoom==='event'}">Zoom to event</button><button type="button" data-zoom="day" aria-pressed="${zoom==='day'}">Show full day</button>${a.kind==='context'?`<button type="button" data-zoom="history" aria-pressed="${zoom==='history'}">Show supporting history</button>`:''}</div><p id="chart-view-range" class="small">${h(time(new Date(epoch(range.start)).toISOString()))} – ${h(time(new Date(epoch(range.end)).toISOString()))} · end exclusive</p>`);
  all('[data-zoom]').forEach(el=>el.onclick=()=>{zoom=el.dataset.zoom;renderInbox();});
  const ranges=[{start:epoch(a.start),end:epoch(a.end),type:'alert'},...(a.evidence_events||[]).map(e=>({start:epoch(e.start),end:epoch(e.end),type:'support'}))];
  const matches=M.overlappingCalendar(records.calendar,[a.building],ranges);
  chart.closest('#investigation').querySelector('.callout').insertAdjacentHTML('beforebegin',`<section class="calendar-context"><div class="overline">OPERATING CALENDAR · ADDITIONAL INTERPRETATION</div><h3>What was scheduled?</h3>${matches.length?matches.map(({entry,matchTypes})=>`<article><strong>${h(entry.title)}</strong><span>${h(M.TYPES[entry.type])} · ${h(scopeName(entry.scope))}${entry.isExample?' · Synthetic demo example':''}</span><time>${h(time(entry.start))} – ${h(time(entry.end))}</time><p>This ${matchTypes.includes('alert')?'alert overlaps':'supporting evidence overlaps'} ${h(M.TYPES[entry.type].toLowerCase())}. This is possible context, not proof that the anomaly is expected or harmless.</p><p>${h(entry.notes)}</p><button type="button" class="text-button" data-calendar-context="${h(entry.id)}">Edit calendar context</button></article>`).join(''):'<p>No calendar entries overlap this alert or its supporting evidence.</p>'}<button type="button" class="text-button" id="add-alert-calendar">+ Add operating context</button></section>`);
  q('#add-alert-calendar').onclick=()=>openCalendar(a);all('[data-calendar-context]').forEach(el=>el.onclick=()=>openCalendar(a,records.calendar.find(e=>e.id===el.dataset.calendarContext)));
  renderFeedback(a);
  all('#inbox .alert-row').forEach(el=>{const item=data.alerts.find(x=>x.id===el.dataset.select),feedback=feedbackFor(item);el.insertAdjacentHTML('beforeend',`<span class="user-outcome">User assessment: ${h(feedback?M.OUTCOMES[feedback.outcome]:'No feedback')}</span>`);});
 }
 function inboxSummary(){const items=visibleAlerts().filter(a=>matchesAlertFilters(a,false)).filter(a=>q('#status-filter').value==='all'||state(a)===q('#status-filter').value);const counts=Object.fromEntries(Object.keys(M.OUTCOMES).map(k=>[k,0]));let none=0;for(const a of items){const f=feedbackFor(a);if(f)counts[f.outcome]++;else none++;}q('#feedback-summary').innerHTML=`<strong>User assessments · not detector accuracy</strong><div>${Object.entries(counts).map(([k,n])=>`<span>${h(M.OUTCOMES[k])}: <b>${n}</b></span>`).join('')}<span>No feedback: <b>${none}</b></span></div><small>Counts use the current building, time, priority, layer, and review-status selection before the outcome filter.</small>`;}
 function meta(a){return `${a.priority} priority · ${scopeName(a.building)} · ${guessTitle(a)} · First detected ${time(new Date(epoch(a.start)).toISOString())} · ${((a.end-a.start)*.25).toFixed(2)} hours flagged`;}
 function chooseAlerts(matches){if(matches.length===1){openAlert(matches[0].id);return;}q('#alert-choices').innerHTML=matches.map(a=>`<button type="button" class="chooser-alert ${a.priority==='High'?'high':'medium'}" data-choice="${h(a.id)}">${h(meta(a))}</button>`).join('');all('[data-choice]').forEach(el=>el.onclick=()=>{q('#alert-chooser').close();openAlert(el.dataset.choice);});q('#alert-chooser').showModal();}
 function decorateChart(el,rows,alerts,{L,T,w,h:height,W,supportWindows=[]}){
  const svg=el.querySelector('svg'),zone=el.querySelector('.hover-zone'),tip=el.querySelector('.chart-tip'),first=rows[0].i,last=rows.at(-1).i;
  const x=i=>L+Math.min(1,Math.max(0,(i-first)/Math.max(1,rows.length-1)))*w;
  const scope=el.id==='chart'?ids():el.id==='detail-chart'?[data.alerts.find(a=>a.id===selected).building]:[q('#lab-building').value];
  const calendar=showCalendar?M.overlappingCalendar(records.calendar,scope,[{start:epoch(first),end:epoch(last+1),type:'chart'}]):[];
  let extras='';
  for(const e of supportWindows){if(e.end<=first||e.start>last)continue;extras+=`<rect class="support-window" x="${x(e.start)}" y="${T+7}" width="${Math.max(3,x(e.end)-x(e.start))}" height="${height-10}" fill="none" stroke="#586b7b" stroke-width="1.6" stroke-dasharray="5 4"/>`;}
  for(const {entry} of calendar){const a=(Date.parse(entry.start)-Date.parse(data.start))/900000,b=(Date.parse(entry.end)-Date.parse(data.start))/900000;extras+=`<rect x="${x(a)}" y="${T+height-13}" width="${Math.max(3,x(b)-x(a))}" height="10" fill="#c9d2db" stroke="#778797" stroke-width="1"><title>${h(entry.title)} · calendar context</title></rect>`;}
  for(const a of alerts.filter(a=>a.id===selected)){if(a.end<=first||a.start>last)continue;extras+=`<rect x="${x(a.start)}" y="${T}" width="${Math.max(4,x(a.end)-x(a.start))}" height="${height}" fill="none" stroke="#173a43" stroke-width="2.4"/>`;}
  const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.classList.add('workspace-chart-overlays');group.setAttribute('pointer-events','none');group.innerHTML=extras;svg.insertBefore(group,el.querySelector('.hover-line'));
  const atEvent=e=>{const rect=svg.getBoundingClientRect(),xx=(e.clientX-rect.left)/rect.width*W;return Math.max(first,Math.min(last,Math.floor((xx-L)/w*Math.max(1,rows.length-1))+first));};
  zone.addEventListener('click',e=>{const matches=M.alertsAt(alerts,atEvent(e));if(matches.length)chooseAlerts(matches);});
  zone.addEventListener('pointermove',e=>{const i=atEvent(e),matches=M.alertsAt(alerts,i),scheduled=calendar.filter(({entry})=>Date.parse(entry.start)<epoch(i+1)&&Date.parse(entry.end)>epoch(i));zone.style.cursor=matches.length?'pointer':'crosshair';if(matches.length||scheduled.length){tip.innerHTML=matches.map(a=>`<strong>${h(meta(a))}</strong>`).join('<hr>')+scheduled.map(({entry})=>`<p>Calendar context: ${h(entry.title)}</p>`).join('');tip.style.display='block';}});
  const real=alerts.filter(a=>a.id);let caption=[];if(calendar.length)caption.push('Lower gray bars: calendar context');if(supportWindows.length)caption.push('Dashed gray outlines: supporting observations, not backdated flags');
  if(caption.length)el.insertAdjacentHTML('beforeend',`<p class="chart-context-legend">${h(caption.join(' · '))}</p>`);
  if(real.length){tip.id=el.id+'-event-tooltip';tip.setAttribute('role','tooltip');el.insertAdjacentHTML('beforeend',`<details class="chart-accessible"><summary>Choose an anomaly from this chart (${real.length})</summary><div>${real.map(a=>`<button type="button" class="chart-event-button ${a.id===selected?'selected':''}" data-chart-event="${h(a.id)}" aria-pressed="${a.id===selected}" aria-describedby="${tip.id}">${h(meta(a))}</button>`).join('')}</div></details>`);el.querySelectorAll('[data-chart-event]').forEach(button=>{const a=real.find(a=>a.id===button.dataset.chartEvent);button.onclick=()=>openAlert(a.id);button.onfocus=()=>{tip.textContent=meta(a);tip.style.display='block';tip.style.left='20px';tip.style.top='25px';};button.onblur=()=>{tip.style.display='none';};});}
 }
 function exportJSON(){const url=URL.createObjectURL(new Blob([JSON.stringify(M.exportRecords(records),null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='meterwise-browser-records.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('#records-status','Export prepared. It contains browser records, not detector training data.');}
 async function previewFile(){pending=null;q('#import-actions').hidden=true;q('#import-preview').replaceChildren();message('#records-status','');message('#records-error','');const file=q('#records-file').files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Choose a JSON file smaller than 2 MB.');const payload=JSON.parse(await file.text()),preview=M.previewImport(payload,records,ctx);pending={preview,baseRaw:lastRaw};const archived=[...preview.feedback,...preview.conflicts.filter(c=>c.kind==='feedback').map(c=>c.incoming)].filter(r=>r.datasetRevision!==ctx.datasetRevision).length;q('#import-preview').innerHTML=`<h3>Import preview · no changes applied</h3><div class="import-counts"><span><b>${preview.calendar.length+preview.feedback.length}</b> Valid new</span><span><b>${preview.invalid.length}</b> Invalid</span><span><b>${preview.conflicts.length}</b> Conflicting</span></div><p>Conflicts already have the same calendar ID or dataset/alert key in this browser.</p>${archived?`<p>${archived} feedback record(s) belong to other dataset fingerprints and will remain archived, not attached to current alerts.</p>`:''}${preview.invalid.length?`<details open><summary>Invalid records</summary><ul>${preview.invalid.map(r=>`<li>${h(r.kind)} record ${r.index}: ${h(r.error)}</li>`).join('')}</ul></details>`:''}${preview.conflicts.length?`<details><summary>Review existing and incoming conflicting records</summary>${preview.conflicts.map(r=>`<article class="import-conflict"><strong>${h(r.kind)} · ${h(r.incoming.id||r.incoming.alertId)}</strong><h4>Existing</h4><pre>${h(JSON.stringify(r.existing,null,2))}</pre><h4>Incoming</h4><pre>${h(JSON.stringify(r.incoming,null,2))}</pre></article>`).join('')}</details>`:''}`;q('#replace-conflicts').checked=false;q('#import-actions').hidden=false;updateApplyLabel();}catch(e){message('#records-error','Import not applied: '+e.message);}}
 function updateApplyLabel(){if(!pending)return;const p=pending.preview,replace=q('#replace-conflicts').checked,count=p.calendar.length+p.feedback.length+(replace?p.conflicts.length:0);q('#apply-import').disabled=!count;q('#apply-import').textContent=replace?`Apply ${count} records, replacing shown conflicts`:`Add ${count} valid new records; keep existing`;}
 function applyImport(){try{if(!pending)throw Error('Choose a file and review its preview first.');if(pending.baseRaw!==lastRaw)throw Error('Records changed since this preview. Choose the file again to review the latest conflicts.');const p=pending.preview,replace=q('#replace-conflicts').checked;write(M.mergeImport(records,p,replace));pending=null;q('#import-actions').hidden=true;q('#import-preview').replaceChildren();message('#records-error','');message('#records-status','Records imported. Invalid entries were skipped; existing conflicts were '+(replace?'replaced by your explicit choice.':'kept.'));render();}catch(e){message('#records-error','Import not applied: '+e.message);}}
 return {calendarEntries:()=>records.calendar.map(e=>({...e})),init,decorateChart,boundsFor,supportingWindows,investigation,inboxSummary,matchesFeedback,alertSelected,focusInvestigation};
})(MeterwiseData);
